//! palette: the colors the designer is working with, each carrying a
//! memory of where it came from (spec q5, provenance).
//!
//! A color that just appears is only half known: the palette list says
//! not only what a color is but how it got there — typed in by hand,
//! extracted from a named image, generated by a scheme from a base
//! color, or imported from a CSS/HTML source. Every path that adds a
//! color stamps it; the stamp travels with the color into the saved
//! project file.

use patois::t;

use crate::{describe_in, ColorFormat, Srgb};

/// How one palette color was added.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Provenance {
	/// The color the app starts with.
	Starter,
	/// Typed in by hand (hex field or the L C H spins).
	Typed,
	/// Extracted from an image file, by file name.
	Extracted { image: String },
	/// Produced by a scheme/shade transform, e.g. "complementary of
	/// #3A7CA5" or "shades of #3A7CA5".
	Generated { scheme: String },
	/// Imported from a CSS or HTML source; the note is the source the
	/// importer recorded, e.g. "custom property --brand-1".
	Imported { source: String },
}

impl Provenance {
	/// The provenance as one spoken phrase, appended to the color's
	/// description in the palette list.
	pub fn spoken(&self) -> String {
		match self {
			Provenance::Starter => t("the color Blind Designer starts with"),
			Provenance::Typed => t("typed in by hand"),
			Provenance::Extracted { image } => {
				t("extracted from image %s").replacen("%s", image, 1)
			}
			Provenance::Generated { scheme } => t("generated as %s").replacen("%s", scheme, 1),
			Provenance::Imported { source } => t("imported from %s").replacen("%s", source, 1),
		}
	}
}

/// The starter colors, offered as an explicit action (Color, Load
/// Starter Colors) rather than pre-loaded: a fresh project's palette
/// is empty and lists only colors the project actually gained, so
/// the starter set joins it only when the user asks for it.
pub fn starter_palette() -> Vec<PaletteColor> {
	vec![PaletteColor::starter(Srgb::new(58, 124, 165))]
}

/// The grayscale start ramp: eight greys from near-black to
/// near-white, the colours a grayscale-start project works with
/// while its shapes are still uncoloured — form first, colour
/// treatment later (see `crate::goals` and the help's GRAYSCALE
/// START section). They join the palette only when asked for,
/// like the starter colours.
pub fn gray_ramp() -> Vec<PaletteColor> {
	[17u8, 51, 85, 119, 153, 187, 221, 238]
		.iter()
		.map(|v| PaletteColor::generated(Srgb::new(*v, *v, *v), &t("the grayscale start ramp")))
		.collect()
}

/// One palette color: the color, the share of the source image it
/// covers when it was extracted from one, and its provenance.
#[derive(Debug, Clone, PartialEq)]
pub struct PaletteColor {
	pub color: Srgb,
	pub coverage: Option<f32>,
	pub provenance: Provenance,
}

impl PaletteColor {
	pub fn new(color: Srgb, provenance: Provenance) -> PaletteColor {
		PaletteColor {
			color,
			coverage: None,
			provenance,
		}
	}

	pub fn starter(color: Srgb) -> PaletteColor {
		PaletteColor::new(color, Provenance::Starter)
	}

	pub fn typed(color: Srgb) -> PaletteColor {
		PaletteColor::new(color, Provenance::Typed)
	}

	pub fn extracted(color: Srgb, coverage: f32, image: &str) -> PaletteColor {
		PaletteColor {
			color,
			coverage: Some(coverage),
			provenance: Provenance::Extracted {
				image: image.to_string(),
			},
		}
	}

	pub fn generated(color: Srgb, scheme: &str) -> PaletteColor {
		PaletteColor::new(
			color,
			Provenance::Generated {
				scheme: scheme.to_string(),
			},
		)
	}

	pub fn imported(color: Srgb, source: &str) -> PaletteColor {
		PaletteColor::new(
			color,
			Provenance::Imported {
				source: source.to_string(),
			},
		)
	}

	/// The palette-list line for this color: its description in the
	/// user's chosen format, its image coverage when it has one, and
	/// where it came from.
	pub fn spoken(&self, format: ColorFormat) -> String {
		let mut s = describe_in(self.color, format);
		if let Some(cov) = self.coverage {
			s.push_str(&t(", covers %s percent of the image").replacen(
				"%s",
				&format!("{:.0}", cov * 100.0),
				1,
			));
		}
		s.push_str(&format!(", {}", self.provenance.spoken()));
		s
	}
}

#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	fn every_provenance_speaks_its_origin() {
		let c = Srgb::new(15, 94, 104);
		assert!(PaletteColor::starter(c)
			.spoken(ColorFormat::Hex)
			.contains("starts with"));
		assert!(PaletteColor::typed(c)
			.spoken(ColorFormat::Hex)
			.contains("typed in by hand"));
		let ex = PaletteColor::extracted(c, 0.42, "photo.jpg").spoken(ColorFormat::Hex);
		assert!(ex.contains("extracted from image photo.jpg"), "{ex}");
		assert!(ex.contains("covers 42 percent of the image"), "{ex}");
		let gen = PaletteColor::generated(c, "complementary of #3A7CA5").spoken(ColorFormat::Hex);
		assert!(
			gen.contains("generated as complementary of #3A7CA5"),
			"{gen}"
		);
		let imp = PaletteColor::imported(c, "custom property --brand-1").spoken(ColorFormat::Hex);
		assert!(
			imp.contains("imported from custom property --brand-1"),
			"{imp}"
		);
	}

	#[test]
	fn starter_palette_is_the_one_starter_blue() {
		let starter = starter_palette();
		assert_eq!(starter.len(), 1);
		assert_eq!(starter[0].color, Srgb::new(58, 124, 165));
		assert_eq!(starter[0].provenance, Provenance::Starter);
		assert!(starter[0].spoken(ColorFormat::Hex).contains("starts with"));
	}

	#[test]
	fn spoken_follows_the_color_format() {
		let pc = PaletteColor::typed(Srgb::new(15, 94, 104));
		assert!(pc.spoken(ColorFormat::Hex).contains("(#0F5E68)"));
		assert!(pc.spoken(ColorFormat::Rgb).contains("(rgb(15, 94, 104))"));
		assert!(pc.spoken(ColorFormat::Hsl).contains("(hsl(187, 75%, 23%))"));
		assert!(pc.spoken(ColorFormat::Hsv).contains("(hsv(187, 86%, 41%))"));
		// A hand-typed color has no image coverage to report.
		assert!(!pc.spoken(ColorFormat::Hex).contains("percent of the image"));
	}
}
